import Link from "next/link";
import { getDashboard, RANGES, type RangeKey } from "@/lib/admin-analytics";
import { formatINR } from "@/lib/money";
import { formatDate, cn } from "@/lib/utils";
import { PageHeader, Panel, StatTile, Table, td } from "@/components/admin/ui";
import { FunnelChart, HBarChart, OrdersChart, RevenueChart } from "@/components/admin/Charts";
import { OrderStatusBadge, statusLabel } from "@/components/OrderStatus";
import { paymentLabel } from "@/components/PaymentBadge";

export default async function AdminDashboard({ searchParams }: PageProps<"/admin">) {
  const r = (await searchParams).range;
  const range: RangeKey = typeof r === "string" && r in RANGES ? (r as RangeKey) : "30d";
  const d = await getDashboard(range);
  const k = d.kpis;

  return (
    <>
      <PageHeader
        title="Dashboard"
        description={`${RANGES[range].label} · all figures in INR, GST inclusive`}
        actions={
          <div className="flex rounded-md border border-line bg-white p-0.5 text-sm" role="tablist" aria-label="Date range">
            {(Object.keys(RANGES) as RangeKey[]).map((key) => (
              <Link key={key} href={`/admin?range=${key}`} role="tab" aria-selected={key === range} className={cn("rounded px-3 py-1.5", key === range ? "bg-ink text-white" : "text-ink-soft hover:bg-paper")}>
                {key.replace("365d", "12m")}
              </Link>
            ))}
          </div>
        }
      />

      {(d.toBeFulfilled > 0 || d.newLeads > 0 || d.lowStock.length > 0) && (
        <div className="mb-6 flex flex-wrap gap-2 text-sm">
          {d.toBeFulfilled > 0 && <Link href="/admin/orders?status=PAID" className="rounded-full bg-blue-100 px-3 py-1 font-medium text-blue-800">{d.toBeFulfilled} orders to fulfil →</Link>}
          {d.newLeads > 0 && <Link href="/admin/leads?status=NEW" className="rounded-full bg-brass-light px-3 py-1 font-medium text-brass">{d.newLeads} new leads / quote requests →</Link>}
          {d.lowStock.length > 0 && <Link href="/admin/products?stock=low" className="rounded-full bg-warn/15 px-3 py-1 font-medium text-warn">{d.lowStock.length} products low on stock →</Link>}
        </div>
      )}

      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatTile delay={0} label="Revenue" value={{ n: k.revenue.value, kind: "inr" }} change={k.revenue.change} />
        <StatTile delay={50} label="Paid orders" value={{ n: k.orders.value, kind: "int" }} change={k.orders.change} />
        <StatTile delay={100} label="Avg. order value" value={{ n: k.aov.value, kind: "inr" }} change={k.aov.change} />
        <StatTile delay={150} label="Conversion rate" value={{ n: k.conversion.value, kind: "pct" }} change={k.conversion.change} />
        <StatTile delay={200} label="Unique visitors" value={{ n: k.visitors.value, kind: "int" }} change={k.visitors.change} />
        <StatTile delay={250} label="New customers" value={{ n: k.newCustomers.value, kind: "int" }} change={k.newCustomers.change} />
        <StatTile delay={300} label="EMI share of revenue" value={{ n: k.emiShare.value, kind: "pct" }} hint="Card EMI + cardless EMI + pay later" />
        <StatTile delay={350} label="Gross margin" value={{ n: k.grossMargin.value, kind: "pct" }} hint="Uses product cost price where set" />
      </div>

      <div className="mt-6 grid gap-6 xl:grid-cols-3">
        <Panel title="Revenue" className="xl:col-span-2">
          <RevenueChart data={d.series} bucket={d.bucket} />
          <p className="mb-2 mt-5 text-sm font-semibold">Paid orders</p>
          <OrdersChart data={d.series} bucket={d.bucket} />
        </Panel>
        <Panel title="Conversion funnel">
          <FunnelChart data={d.funnel} />
          <p className="mt-4 text-xs text-muted">Unique visitors reaching each step. Percentages are step-to-step conversion.</p>
        </Panel>
      </div>

      <div className="mt-6 grid gap-6 lg:grid-cols-2">
        <Panel title="Revenue by payment method">
          <HBarChart data={d.byMethod.map((m) => ({ label: `${paymentLabel(m.method)} (${m.orders})`, revenue: m.revenue }))} labelKey="label" valueKey="revenue" />
        </Panel>
        <Panel title="Revenue by category">
          <HBarChart data={d.byCategory.map((c) => ({ label: c.name, revenue: c.revenue }))} labelKey="label" valueKey="revenue" />
        </Panel>
      </div>

      <div className="mt-6 grid gap-6 xl:grid-cols-3">
        <Panel title="Top products" className="xl:col-span-2" action={<Link href="/admin/products" className="text-sm text-maroon hover:underline">All products</Link>}>
          <Table head={["Product", "Units", "Revenue", "Views", "View→buy", "Stock"]}>
            {d.topProducts.map((p) => (
              <tr key={p.id}>
                <td className={td}><Link href={`/admin/products/${p.id}`} className="font-medium hover:text-maroon">{p.name}</Link></td>
                <td className={cn(td, "tabular-nums")}>{p.units}</td>
                <td className={cn(td, "tabular-nums")}>{formatINR(p.revenue)}</td>
                <td className={cn(td, "tabular-nums")}>{p.views}</td>
                <td className={cn(td, "tabular-nums")}>{p.views ? `${((p.units / p.views) * 100).toFixed(1)}%` : "—"}</td>
                <td className={cn(td, "tabular-nums", p.stock <= 5 && "font-semibold text-warn")}>{p.stock}</td>
              </tr>
            ))}
          </Table>
          {!d.topProducts.length && <p className="py-6 text-center text-sm text-muted">No sales in this period yet.</p>}
        </Panel>
        <div className="space-y-6">
          <Panel title="Order status (orders created in period)">
            <ul className="space-y-1.5 text-sm">
              {d.statusCounts.sort((a, b) => b.count - a.count).map((s) => (
                <li key={s.status} className="flex justify-between"><span>{statusLabel(s.status)}</span><span className="font-semibold tabular-nums">{s.count}</span></li>
              ))}
            </ul>
          </Panel>
          <Panel title="Top searches">
            {d.searches.length ? (
              <ul className="space-y-1.5 text-sm">{d.searches.map((s) => <li key={s.q} className="flex justify-between"><span>“{s.q}”</span><span className="tabular-nums text-muted">{s.count}</span></li>)}</ul>
            ) : <p className="text-sm text-muted">No searches recorded yet.</p>}
          </Panel>
        </div>
      </div>

      <div className="mt-6 grid gap-6 xl:grid-cols-[1.5fr_1fr]">
        <Panel title="Recent orders" action={<Link href="/admin/orders" className="text-sm text-maroon hover:underline">View all</Link>}>
          <Table head={["Order", "Customer", "Total", "Payment", "Status"]}>
            {d.recentOrders.map((o) => (
              <tr key={o.id}>
                <td className={td}><Link href={`/admin/orders/${o.id}`} className="font-medium hover:text-maroon">#{o.orderNumber}</Link><span className="block text-xs text-muted">{formatDate(o.createdAt, true)}</span></td>
                <td className={td}>{(o.shippingAddress as { name?: string }).name}</td>
                <td className={cn(td, "tabular-nums")}>{formatINR(o.total)}</td>
                <td className={td}>{paymentLabel(o.paymentMethod)}</td>
                <td className={td}><OrderStatusBadge status={o.status} /></td>
              </tr>
            ))}
          </Table>
        </Panel>
        <Panel title="Low stock" action={<Link href="/admin/products?stock=low" className="text-sm text-maroon hover:underline">Manage</Link>}>
          {d.lowStock.length ? (
            <Table head={["Product", "SKU", "Stock"]}>
              {d.lowStock.map((p) => (
                <tr key={p.id}>
                  <td className={td}><Link href={`/admin/products/${p.id}`} className="hover:text-maroon">{p.name}</Link></td>
                  <td className={cn(td, "text-muted")}>{p.sku}</td>
                  <td className={cn(td, "font-semibold tabular-nums", p.stock === 0 ? "text-danger" : "text-warn")}>{p.stock === 0 ? "Out of stock" : p.stock}</td>
                </tr>
              ))}
            </Table>
          ) : <p className="text-sm text-muted">All products are above their low-stock threshold.</p>}
        </Panel>
      </div>
    </>
  );
}
